def solve(xs: list[float]) -> list[float]:
    # Naive O(n^2): re-sum the whole prefix at every index.
    return [sum(xs[: i + 1]) for i in range(len(xs))]
def solve(xs: list[float]) -> list[float]:
    # O(n): carry a running total instead of re-summing each prefix.
    out: list[float] = []
    total = 0.0
    for x in xs:
        total += x
        out.append(total)
    return out
import itertools


def solve(xs: list[float]) -> list[float]:
    # O(n) in C: itertools.accumulate does the running sum natively.
    return list(itertools.accumulate(xs))
